                        lsbs -= d;
                }
                /* compose the value */
                uval = msbs * parameter + lsbs;
        }

        /* unfold uint32_t to signed */
        if(uval & 1)
                *val = -((int)(uval >> 1)) - 1;
        else
                *val = (int)(uval >> 1);

        return true;
}

